const OPEN = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" shape-rendering="crispEdges">`
// The still picture, drawn once as an image.
export const base = `${OPEN}${BASE}</svg>`
// What moves for a pose, on a transparent canvas laid over the base.
export const overlay = (pose: Pose) => `${OPEN}${POSES[pose]}${COMMON}</svg>`
// Eyes on the monitor and moving hands, shown under the overlay while working.
export const working = `${OPEN}${WORKING}</svg>`
// Context nearly full: drawn above whatever pose is showing.
export const alarm = `${OPEN}<rect x="55" y="35" width="8" height="7" fill="#f0bf82"/><rect x="56" y="35" width="6" height="6" fill="#ffffff"/><rect x="58" y="37" width="2" height="2" fill="#2b2325"/><rect x="74" y="35" width="8" height="7" fill="#f0bf82"/><rect x="75" y="35" width="6" height="6" fill="#ffffff"/><rect x="77" y="37" width="2" height="2" fill="#2b2325"/><g fill="#7cc6f2"><rect x="46" y="40" width="1" height="1"/><rect x="45" y="41" width="3" height="3"/><rect x="46" y="44" width="1" height="1"/><animateTransform attributeName="transform" type="translate" values="0 0;0 1;0 2;0 3" dur="1.2s" calcMode="discrete" repeatCount="indefinite"/></g><g fill="#d93a3a"><rect x="96" y="1" width="3" height="7"/><rect x="96" y="9" width="3" height="2"/><animate attributeName="opacity" values="1;0.35" dur="0.8s" begin="0s" calcMode="discrete" repeatCount="indefinite"/></g></svg>`
export const isWorking = (pose: Pose) => pose === 'think' || pose === 'read' || pose === 'edit' || pose === 'bash' || pose === 'delegate'
// Base and overlay in one picture (previews).
export const sprite = (pose: Pose) =>
  `${OPEN}${BASE}${isWorking(pose) ? WORKING : ''}${POSES[pose]}${COMMON}</svg>`
